const body = $input.first().json.body ?? $input.first().json;
const projectId = String(body.projectId || 'glassbox-studio-template').trim();
const text =
  (body.body && body.body.text) ||
  body.text ||
  body.message ||
  (typeof body === 'string' ? body : JSON.stringify(body));
const channel = ['email','slack','telegram','whatsapp','sms','webhook','other'].includes(body.channel)
  ? body.channel
  : 'webhook';
const conversationId = String(
  body.conversationId ||
  body.threadId ||
  `n8n:${channel}:${body.from?.address || body.from || 'anon'}`
);
return [{
  json: {
    projectId,
    envelope: {
      conversationId,
      channel,
      direction: body.direction === 'out' ? 'out' : 'in',
      from: body.from && typeof body.from === 'object'
        ? body.from
        : { name: String(body.from || 'n8n'), address: 'n8n' },
      to: body.to,
      body: { text: String(text || '').trim() || '(empty)' },
      status: body.status === 'read' ? 'read' : 'unread',
      hasAttachment: Boolean(body.hasAttachment),
    },
  },
}];
